// Supabase devuelve un ítem por fila. Si la tabla está vacía llega un ítem vacío,
// porque «Listar ideas» tiene activado Always Output Data: así la API responde igual.
const ideas = $input.all().map((item) => item.json).filter((fila) => fila.id !== undefined);
return [{ json: { cantidad: ideas.length, ideas } }];

// Revisamos el pedido antes de tocar la base: si falta algo, la API responde 400
// con la lista de errores, y en Supabase entran nada más filas completas.
const NIVELES = ['inicial', 'intermedio', 'avanzado'];
let cuerpo = $input.first().json.body ?? {};
if (typeof cuerpo === 'string') {
  try {
    cuerpo = JSON.parse(cuerpo);
  } catch {
    cuerpo = {};
  }
}
const texto = (valor) => (typeof valor === 'string' ? valor.trim() : '');

const nombre = texto(cuerpo.nombre);
const idea = texto(cuerpo.idea);
const nivel = texto(cuerpo.nivel).toLowerCase() || 'inicial';

const errores = [];
if (!nombre) errores.push('Falta «nombre».');
else if (nombre.length > 120) errores.push('«nombre» tiene más de 120 caracteres.');
if (!idea) errores.push('Falta «idea».');
else if (idea.length > 2000) errores.push('«idea» tiene más de 2000 caracteres.');
if (!NIVELES.includes(nivel)) errores.push(`«nivel» tiene que ser ${NIVELES.join(', ')}.`);

return [{ json: { valido: errores.length === 0, errores, fila: { nombre, idea, nivel } } }];
